import { Component, inject } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { HrmButton, HrmCommandPaletteService } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Command Palette (Overlay) — hộp tìm lệnh nhanh Ctrl/⌘+K. Song ngữ qua i18n docs.commandPalette.*.
 *  Component đặt 1 lần ở shell (styleguide đã gắn sẵn); trang này chỉ mở service. */
@Component({
  selector: 'sg-doc-command-palette',
  imports: [TranslateModule, HrmButton, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Overlay" [title]="'docs.commandPalette.title' | translate" [desc]="'docs.commandPalette.desc' | translate">

      <div sgOverview>
        <sg-row>
          <hrm-button variant="primary" (click)="palette.open()">{{ 'docs.commandPalette.ovOpen' | translate }}</hrm-button>
          <span class="kbd-hint" [innerHTML]="'docs.commandPalette.kbdHint' | translate"></span>
        </sg-row>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.commandPalette.purpose' | translate"
          [when]="when"
          [behavior]="'docs.commandPalette.behavior' | translate"
          [avoid]="'docs.commandPalette.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.commandPalette.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.commandPalette.do2' | translate }}</sg-do>
        <sg-do>{{ 'docs.commandPalette.do3' | translate }}</sg-do>
        <sg-dont>{{ 'docs.commandPalette.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.commandPalette.exTryT' | translate"
          [desc]="'docs.commandPalette.exTryD' | translate">
          <sg-row>
            <hrm-button (click)="palette.open()">{{ 'docs.commandPalette.exTryOpen' | translate }}</hrm-button>
          </sg-row>
        </sg-example>
      </div>

    </sg-doc>
  `,
  styles: [`
    .kbd-hint { display: inline-flex; align-items: center; gap: 4px; font-size: var(--fs-13); color: var(--text-sub); }
    kbd {
      font-family: var(--font-sans); font-size: var(--fs-12); color: var(--text-body);
      background: var(--bg-surface-subtle); border: 1px solid var(--border-sub);
      border-bottom-width: 2px; border-radius: var(--radius-sm); padding: 1px 6px;
    }
  `],
})
export class SgDocCommandPalette {
  protected readonly palette = inject(HrmCommandPaletteService);
  protected readonly when = [
    'docs.commandPalette.when1',
    'docs.commandPalette.when2',
    'docs.commandPalette.when3',
  ];
}
